cypress_script:
describe('Bank Login and Navigation', () => {
  it('should log in successfully with valid credentials', () => {
    cy.visit('https://parabank.parasoft.com/parabank/index.htm');
    cy.get('input[name="username"]').type('validUser');
    cy.get('input[name="password"]').type('validPassword');
    cy.get('input[value="Log In"]').click();
    cy.url().should('include', '/dashboard'); // Assuming successful login redirects here
  });
  it('should not log in with invalid credentials', () => {
    cy.visit('https://parabank.parasoft.com/parabank/index.htm');
    cy.get('input[name="username"]').type('invalidUser');
    cy.get('input[name="password"]').type('invalidPassword');
    cy.get('input[value="Log In"]').click();
    cy.url().should('include', '/parabank/index.htm'); // Assuming stays on login page
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Bank Login and Navigation', () => {
  test('should log in successfully with valid credentials', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/index.htm');
    await page.fill('input[name="username"]', 'validUser');
    await page.fill('input[name="password"]', 'validPassword');
    await page.click('input[value="Log In"]');
    await page.waitForURL('**/dashboard'); // Assuming successful login redirects here
  });
  test('should not log in with invalid credentials', async ({ page }) => {
    await page.goto('https://parabank.parasoft.com/parabank/index.htm');
    await page.fill('input[name="username"]', 'invalidUser');
    await page.fill('input[name="password"]', 'invalidPassword');
    await page.click('input[value="Log In"]');
    await page.waitForURL('**/parabank/index.htm'); // Assuming stays on login page
  });
});
